import{c as l,$ as e,Q as r,j as o,g as s,o as n,n as i,m as d}from"./chunks/framework.Ce_49mA8.js";const v=JSON.parse('{"title":"Имущество и ресурсы","description":"Практическое руководство по учету личной недвижимости, транспорта, оборудования мастерских и запасов сырья в ОмниКрафт ЕРП.","frontmatter":{"title":"Имущество и ресурсы","description":"Практическое руководство по учету личной недвижимости, транспорта, оборудования мастерских и запасов сырья в ОмниКрафт ЕРП.","datePublished":"2026-10-28","dateModified":"2026-11-15","order":17},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/property.md","filePath":"ru/docs/spaces/moy-kapital/property.md","lastUpdated":1794700800000}'),p={name:"ru/docs/spaces/moy-kapital/property.md"},c={id:"имущество-и-ресурсы-единыи-материальныи-реестр",tabindex:"-1"};function g(h,t,m,u,f,b){const a=e("DocIcon");return r(),o("div",null,[s("h1",c,[n(a,{name:"capital"}),t[0]||(t[0]=i(" Имущество и ресурсы: Единый материальный реестр ",-1)),t[1]||(t[1]=s("a",{class:"header-anchor",href:"#имущество-и-ресурсы-единыи-материальныи-реестр","aria-label":'Permalink to "Имущество и ресурсы: Единый материальный реестр"'},"​",-1))]),t[2]||(t[2]=d('<p>Вкладка <strong>«Имущество и ресурсы»</strong> объединяет все физические активы мастера в единый материальный реестр. В отличие от операционной наличности на счетах и биржевых инструментов, здесь сосредоточены долгосрочные материальные ценности: жилая и коммерческая недвижимость, склады, производственные помещения, рабочий автотранспорт, парки станков, швейные и раскройные комплексы, ручной инструмент и стратегические складские запасы сырья.</p><p>Материальные ресурсы составляют фундаментальную основу ремесленного дела. Реальная капитализация мастера складывается не только из свободных денег на картах, но и из совокупной рыночной стоимости производственной базы и личного имущества, обеспечивающего финансовую устойчивость мастерской.</p><hr><h2 id="архитектура-материальных-фондов" tabindex="-1">Архитектура материальных фондов <a class="header-anchor" href="#архитектура-материальных-фондов" aria-label="Permalink to &quot;Архитектура материальных фондов&quot;">​</a></h2><p>Физические активы в ОмниКрафт ЕРП сгруппированы в четыре базовых контура:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>Недвижимость и земля:</strong><br> Мастерские, склады, производственные и жилые площади, земельные участки. </div></li><li><span class="craft-list-bullet"></span><div><strong>Транспортные средства:</strong><br> Коммерческие фургоны, прицепы, логистический и личный автотранспорт. </div></li><li><span class="craft-list-bullet"></span><div><strong>Оборудование и станки:</strong><br> Швейные машины, ЧПУ-станки, лазерные раскройщики, верстаки и специализированная оснастка. </div></li><li><span class="craft-list-bullet"></span><div><strong>Материалы и запасы:</strong><br> Складские остатки сырья, фурнитуры, расходных материалов и упаковочной тары. </div></li></ul><p>Такая консолидация решает фундаментальную задачу разделения капитала: система связывает ресурсы производственных и сервисных цехов с личным балансом владельца, исключая потерю контроля над дорогостоящими станками и накопленным сырьем.</p><hr><h2 id="сводные-индикаторы-и-фильтрация-реестра" tabindex="-1">Сводные индикаторы и фильтрация реестра <a class="header-anchor" href="#сводные-индикаторы-и-фильтрация-реестра" aria-label="Permalink to &quot;Сводные индикаторы и фильтрация реестра&quot;">​</a></h2><p>В верхней части экрана расположена панель ключевых показателей материальных активов:</p><table class="craft-matrix-table"><thead><tr><th style="width:28%;">Всё имущество</th><th style="width:24%;">Недвижимость / авто</th><th style="width:24%;">Оборудование</th><th style="width:24%;">Запасы сырья</th></tr></thead><tbody><tr><td><strong>7 450 000,00 ₽</strong></td><td>5 200 000,00 ₽</td><td>1 450 000,00 ₽</td><td>800 000,00 ₽</td></tr></tbody></table><ul><li><strong>«Все имущество и материалы»:</strong> общая рыночная стоимость всех материальных ресурсов с учетом персональной доли владения мастера;</li><li><strong>«Недвижимость и авто»:</strong> оценочная стоимость зданий, производственных площадей, гаражей и транспортных средств;</li><li><strong>«Оборудование и станки»:</strong> балансовая стоимость парка машин, раскройных комплексов и профессионального инструмента цехов;</li><li><strong>«Материалы и запасы»:</strong> совокупная себестоимость текущих остатков сырья, кожи, дерева, металла и комплектующих на всех складах рабочих пространств.</li></ul><h3 id="сегментныи-фильтр-категории" tabindex="-1">Сегментный фильтр категорий <a class="header-anchor" href="#сегментныи-фильтр-категории" aria-label="Permalink to &quot;Сегментный фильтр категорий&quot;">​</a></h3><p>Под панелью индикаторов находится переключатель категорий для быстрой сортировки объектов:</p><ul><li><strong>«Все позиции»:</strong> сквозной перечень всех материальных активов мастера;</li><li><strong>«Недвижимость и авто»:</strong> изолированный список объектов недвижимости и транспорта;</li><li><strong>«Оборудование и станки»:</strong> реестр основных производственных средств и инструмента;</li><li><strong>«Материалы и запасы»:</strong> реестр сырьевых складских запасов с детальной оценкой остатков.</li></ul><div class="tip custom-block"><p class="custom-block-title">Разделение ликвидности и материальной базы</p><p>Никогда не смешивайте оборотные деньги на счетах со стоимостью станков. Станок нельзя мгновенно потратить на закупку партии кожи или оплату аренды без остановки рабочего процесса. Четкое разделение на ликвидные счета и материальный реестр защищает от иллюзии избытка свободных денег.</p></div><hr><h2 id="трехсторонняя-модель-долеи-владения" tabindex="-1">Трехсторонняя модель долей владения <a class="header-anchor" href="#трехсторонняя-модель-долеи-владения" aria-label="Permalink to &quot;Трехсторонняя модель долей владения&quot;">​</a></h2><p>Главная инженерная особенность модуля «Имущество и ресурсы» — поддержка совместного использования и долевой собственности между личной жизнью и рабочими пространствами.</p><p>Один и тот же материальный ресурс может одновременно служить семье мастера, использоваться для выпуска серийных изделий и обеспечивать сервисные выезды. Для каждого объекта настраивается персональное соотношение долей:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Личное пользование] + [Производство] + [Сервисный центр] = 100.00%</span></span></code></pre></div><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Материальный капитал</span><div class="formula-heading">Расчет вклада имущества в совокупный чистый капитал</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Вклад в капитал (₽)</span><span class="math-op">=</span><span class="math-var">Текущая рыночная оценка</span><span class="math-op">×</span><span class="math-frac"><span class="math-num">Доля владения мастера (%)</span><span class="math-denom">100%</span></span></div></div><div class="formula-card-bottom"><p>Если станок или помещение приобретены в партнерстве, программа рассчитывает чистый капитал строго пропорционально личной доле владельца. При списании амортизации нагрузка распределяется между цехами пропорционально установленным долям использования.</p></div></div><h3 id="балансировка-долеи-по-методу-гамильтона" tabindex="-1">Балансировка долей по методу Гамильтона <a class="header-anchor" href="#балансировка-долеи-по-методу-гамильтона" aria-label="Permalink to &quot;Балансировка долей по методу Гамильтона&quot;">​</a></h3><p>В окне настройки долей владения реализован математический алгоритм пропорционального пересчета (метод наибольших остатков Гамильтона). При изменении процента для одного направления программа автоматически корректирует остальные показатели, гарантируя строгое соблюдение баланса 100.00% (10 000 базисных пунктов) без ошибок округления.</p><p><strong>Пример из практики цеха:</strong></p><p>Мастер приобретает вместительный универсальный фургон за 2 500 000 ₽:</p><ol><li><strong>Личное пользование (40%):</strong> поездки семьи, загородные выезды и бытовые нужды;</li><li><strong>Производство (40%):</strong> доставка оптовых партий сырья от поставщиков и развоз готовой продукции;</li><li><strong>Сервисный центр (20%):</strong> выезды мастера на диагностику, установку и гарантийное обслуживание изделий.</li></ol><p>В личный баланс мастера автомобиль включается в полном объеме личной собственности, а накладные расходы на техническое обслуживание и амортизацию списываются на себестоимость соответствующих цехов по установленным квотам.</p><hr><h2 id="внесение-активов-и-параметры-карточки" tabindex="-1">Внесение активов и параметры карточки <a class="header-anchor" href="#внесение-активов-и-параметры-карточки" aria-label="Permalink to &quot;Внесение активов и параметры карточки&quot;">​</a></h2><p>Для добавления нового объекта нажмите кнопку <strong>«Внести личный актив»</strong>. В открывшемся окне заполняются параметры имущества:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Поле ввода</th><th style="text-align:left;">Назначение и формат</th><th style="text-align:left;">Пример значения</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>«Название актива»</strong></td><td style="text-align:left;">Полное наименование объекта или марки станка</td><td style="text-align:left;"><em>Фортуна САС двоильная машина</em>, <em>Фургон Соболь NN</em></td></tr><tr><td style="text-align:left;"><strong>«Тип актива»</strong></td><td style="text-align:left;">Контур назначения (Личное имущество / Инвестиции)</td><td style="text-align:left;"><em>Личное имущество</em></td></tr><tr><td style="text-align:left;"><strong>«Категория актива»</strong></td><td style="text-align:left;">Отраслевая группа для фильтрации и аналитики</td><td style="text-align:left;"><em>Недвижимость / Земля</em>, <em>Транспортные средства</em>, <em>Прочие ценные вещи</em></td></tr><tr><td style="text-align:left;"><strong>«Дата приобретения»</strong></td><td style="text-align:left;">Дата ввода в эксплуатацию или покупки</td><td style="text-align:left;"><em>2026-03-15</em> (выбор в календаре)</td></tr><tr><td style="text-align:left;"><strong>«Стоимость покупки»</strong></td><td style="text-align:left;">Первоначальные фактические затраты на покупку и пусконаладку</td><td style="text-align:left;"><em>350 000,00 ₽</em></td></tr><tr><td style="text-align:left;"><strong>«Текущая оценочная стоимость»</strong></td><td style="text-align:left;">Реалистичная ликвидационная оценка на текущую дату</td><td style="text-align:left;"><em>310 000,00 ₽</em></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Консервативная ликвидационная оценка</p><p>Для дорогостоящих станков и транспорта всегда указывайте консервативную рыночную стоимость — сумму, за которую объект гарантированно удастся продать в течение 2–3 недель при срочной потребности в ликвидности. Завышение оценки создает иллюзорное чувство безопасности и искажает управленческий баланс.</p></div><hr><h2 id="аудит-фондов-и-устранение-коллизии" tabindex="-1">Аудит фондов и устранение коллизий <a class="header-anchor" href="#аудит-фондов-и-устранение-коллизии" aria-label="Permalink to &quot;Аудит фондов и устранение коллизий&quot;">​</a></h2><p>Когда мастер параллельно ведет учет оборудования в производственной мастерской и вносит личные активы, возникает риск задвоения записей: один и тот же раскройный плоттер может случайно оказаться записан и как станок цеха, и как личное имущество.</p><p>Для проверки чистоты учета предназначена кнопка <strong>«🛡️ Проверить дубликаты и коллизии»</strong>:</p><ol><li><strong>Коллизии долей владения:</strong> сканер проверяет все активные карточки на предмет расхождения суммы долей с нормативными 100.00%. При обнаружении ошибки кнопка <strong>«Исправить доли (100%)»</strong> приводит коэффициенты к балансу;</li><li><strong>Потенциальные дубликаты оборудования:</strong> система сопоставляет наименования личных активов с реестром вкладки «Мастерская / Активы». Кнопка <strong>«Объединить дубликаты»</strong> объединяет дублирующие записи в единую мастер-карточку со сквозными долями;</li><li><strong>Потенциальные дубликаты сырья:</strong> поиск пересечений между личными материальными запасами и операционными складскими остатками.</li></ol><div class="tip custom-block"><p class="custom-block-title">Регулярность аудита</p><p>Запускайте проверку коллизий после масштабных закупок оборудования, реорганизации цеха или ежегодной инвентаризации остатков. Это гарантирует отсутствие «воздушных» миллионов в отчете о капитале.</p></div><hr><h2 id="защита-от-случаиного-удаления-и-регламент-архивации" tabindex="-1">Защита от случайного удаления и регламент архивации <a class="header-anchor" href="#защита-от-случаиного-удаления-и-регламент-архивации" aria-label="Permalink to &quot;Защита от случайного удаления и регламент архивации&quot;">​</a></h2><p>Физические активы тесно переплетены с другими модулями программы: на оборудовании рассчитывается себестоимость машино-часа в калькуляторе рецептов, а материалы списываются при выпуске партий готовой продукции.</p><p>В ОмниКрафт ЕРП действует строгий стандарт безопасности данных:</p><ul><li><strong>Двухконтурная защита удаления (умный барьер списания):</strong> программа блокирует удаление объекта, если он участвует в калькуляциях изделий, задействован в открытых заказ-нарядах или имеет связанные складские транзакции;</li><li><strong>Штатное списание и архивация:</strong> при продаже станка или списании изношенного инструмента карточка переводится в архив кнопкой <strong>«Удалить / списать»</strong>. При этом в базе сохраняются все исторические расчеты прошлых партий, а текущий баланс материальных фондов уменьшается на выбывшую сумму;</li><li><strong>Сквозная фиксация выручки:</strong> при продаже оборудования вырученные средства зачисляются на выбранный счет во вкладке <strong>«Счета и кошельки»</strong>, обеспечивая непрерывность движения капитала.</li></ul><div class="warning custom-block"><p class="custom-block-title">Сохранение истории расчетов</p><p>Никогда не пытайтесь обнулять или принудительно стирать карточки оборудования прошлых лет. Архивирование сохраняет доказательную базу для налогового и управленческого учета, защищая ретроспективную аналитику от искажений.</p></div>',45))])}const x=l(p,[["render",g]]);export{v as __pageData,x as default};
